--
-- Table structure for table `consultation_summary`
--

DROP TABLE IF EXISTS `consultation_summary`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `consultation_summary` (
  `summary_id` bigint NOT NULL AUTO_INCREMENT,
  `consultation_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `summary_text` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `start_location_label` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `guided_exit_facility_id` bigint DEFAULT NULL,
  `guided_exit_label` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `route_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `completed_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`summary_id`),
  UNIQUE KEY `uk_consultation_summary_consultation` (`consultation_id`),
  KEY `fk_consultation_summary_exit` (`guided_exit_facility_id`),
  CONSTRAINT `fk_consultation_summary_exit` FOREIGN KEY (`guided_exit_facility_id`) REFERENCES `facility` (`facility_id`),
  CONSTRAINT `fk_consultation_summary_session` FOREIGN KEY (`consultation_id`) REFERENCES `consultation_session` (`consultation_id`)
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

