INSERT INTO `consultation_summary` VALUES (1,'cs_50d0e466ab944be383947e14690f361a','COMPLETED','상담원은 가장 가까운 출구를 안내했다.',NULL,NULL,NULL,NULL,'2026-08-03 16:43:30.366064','2026-08-03 16:43:31.607717'),(2,'cs_634592a5ad7d471ab5754793ad085675','COMPLETED','상담원은 명절에 대한 안내를 시작했다.',NULL,NULL,NULL,NULL,'2026-08-03 17:20:17.050700','2026-08-03 17:20:18.232678'),(3,'cs_497da78d011f43e4b80c1bbd5ab43e2e','COMPLETED','상담원은 사용자의 음성 인식 및 번역 오류에 대해 영어 음성 입력 및 텍스트 입력 테스트를 안내했습니다.',NULL,NULL,NULL,NULL,'2026-08-03 17:26:07.223856','2026-08-03 17:26:08.329637'),(4,'cs_4056e3d72e0c44599b058b22eaa4a0ad','COMPLETED','상담원은 사용자의 요청 취소 및 상담 화면 이탈 가능성에 대해 안내했다.',NULL,NULL,NULL,NULL,'2026-08-04 10:54:47.390652','2026-08-04 10:54:48.499529'),(5,'cs_55cb3b12ee2f4e0dac59e659eb754c8f','COMPLETED','상담원은 취소 요청이 정상적으로 처리되지 않은 상황에 대한 안내를 완료했다.',NULL,NULL,NULL,NULL,'2026-08-04 10:55:42.948962','2026-08-04 10:55:43.946964'),(6,'cs_62f6c621b17241409aa38b9218c1c955','COMPLETED','상담원이 어제 있었던 일을 안내 완료.',NULL,NULL,NULL,NULL,'2026-08-04 06:45:49.240374','2026-08-04 06:45:50.512428'),(7,'cs_4aaca9cd3b0e42cfaec9396b44ab687d','COMPLETED','상담원은 새로고침 시 기록이 리셋되고 경고 표시가 사라진다고 안내했다.',NULL,NULL,NULL,NULL,'2026-08-04 08:13:19.644068','2026-08-04 08:13:20.812524'),(8,'cs_9e6ba2dac8884d7e93111627a495879a','COMPLETED','상담자는 고객의 요청에 따라 특정 인물(Yogi)을 호출하고 물건 구매에 대한 대화를 진행했습니다.',NULL,NULL,NULL,NULL,'2026-08-04 08:16:00.798566','2026-08-04 08:16:02.059869'),(9,'cs_60c4b41c5359471a8f3b46950d7ae69a','COMPLETED','상담원은 카메라 화면이 작게 나오고 확대 시 깨지는 문제와 핸드폰 마이크 인식 불가 문제를 확인하고 안내했다.',NULL,NULL,NULL,NULL,'2026-08-05 00:52:12.152637','2026-08-05 00:52:13.554313'),(10,'cs_e36fdb2327074080890d7a86d804008a','COMPLETED','상담원은 카메라 연결 및 자막 오류를 확인하고 수정 방법을 안내했다.',NULL,NULL,NULL,NULL,'2026-08-05 01:05:18.657992','2026-08-05 01:05:19.591699'),(11,'cs_fe5a3db859814d0d96988591ef46c099','COMPLETED','상담원은 외국인 승객에게 영어로 안내를 제공했다.',NULL,NULL,NULL,NULL,'2026-08-05 01:10:23.673294','2026-08-05 01:10:24.733189'),(12,'cs_86bd55e768b84d40a94c97e8d171e872','COMPLETED','상담원은 사용자 마이크 이슈 발생 여부와 영어 응대 가능 여부를 확인하고 안내 완료.',NULL,NULL,NULL,NULL,'2026-08-05 01:22:54.434165','2026-08-05 01:22:55.881925'),(13,'cs_9724fe6ce8c24c6c83e61bc96ce64ed7','COMPLETED','상담원은 사용자 시점 따라가기 기능 오류와 자막 중복 출력 문제를 해결하기 위한 UI 분리 또는 초기화 방안을 제시했다.',NULL,NULL,NULL,NULL,'2026-08-05 01:49:08.562133','2026-08-05 01:49:09.765574'),(14,'cs_0dabcc612a494ca5a132ff4f3e76a0ae','COMPLETED','상담원은 역 내 시설 정보가 부족함을 인지하고, 기본적인 시설 정보만 제공하도록 시스템 개선을 제안했다.',NULL,NULL,NULL,NULL,'2026-08-05 01:59:09.866311','2026-08-05 01:59:10.898461'),(15,'cs_70885636110540b5a8a14f08ac79243e','COMPLETED','상담원은 지하철역 개발 계획에 대해 안내했다.',NULL,NULL,NULL,NULL,'2026-08-05 03:07:45.894563','2026-08-05 03:07:47.108231'),(16,'cs_ce1109960ae441309196c6d89568e64f','COMPLETED','상담원은 STT 기능과 번역 기능에 대해 설명하고, 영어 번역 시 문장 완성의 중요성을 안내했다.',NULL,NULL,NULL,NULL,'2026-08-05 03:19:23.038947','2026-08-05 03:19:24.395388'),(17,'cs_0635095f754044cea5d70cfa10a5090e','COMPLETED','상담원은 캐리어가 자동으로 움직이는 현상에 대한 안내를 완료했다.',NULL,NULL,NULL,NULL,'2026-08-05 03:22:43.660026','2026-08-05 03:22:44.620578'),(18,'cs_d9cecc0670374554959bd4be191ecc29','COMPLETED','상담원은 버전 20으로 업데이트 후 발생한 문제를 해결하기 위해 서버 재정비 및 코드 확인을 안내했다.',NULL,NULL,NULL,NULL,'2026-08-05 04:23:39.471503','2026-08-05 04:23:40.712366'),(19,'cs_7620a5f915634d4bb53da17b9db63b4b','COMPLETED','상담원은 아이폰 카메라 오류 발생 원인을 파악하고 해결 방법을 안내하려 했으나, 문제 해결에 어려움을 겪었다.',NULL,NULL,NULL,NULL,'2026-08-05 04:52:47.487535','2026-08-05 04:52:48.865940'),(20,'cs_1824328b104d4eed87195e7852bc3759','COMPLETED','상담원은 마이크에 대한 안내를 완료했습니다.',NULL,NULL,NULL,NULL,'2026-08-05 04:54:02.538179','2026-08-05 04:54:03.481890'),(21,'cs_06ae53ce45184940a8ad65762124b894','COMPLETED','상담자는 긍정적인 반응을 보이며 대화를 마무리했다.',NULL,NULL,NULL,NULL,'2026-08-05 05:55:57.362679','2026-08-05 05:55:58.844328'),(22,'cs_027a9d6de7ea447b9ceb6a8c01f86b34','COMPLETED','상담원은 지도, 카메라, 층별 안내, 위치 이동, 소리 켜기 기능에 대한 안내를 완료했다.',NULL,NULL,NULL,NULL,'2026-08-05 06:35:15.955996','2026-08-05 06:35:17.051266'),(23,'cs_09c89f22da474a6ba6d8e1c195072d9e','COMPLETED','상담원은 영어로 자기소개를 안내했다.',NULL,NULL,NULL,NULL,'2026-08-05 06:36:51.780595','2026-08-05 06:36:52.698043'),(24,'cs_7e0aaa2339c54ec5b413ae2699ff846f','COMPLETED','상담원은 시스템 오류로 인해 사용자 발언이 상담원 발언으로 인식되는 문제를 설명함.',NULL,NULL,NULL,NULL,'2026-08-05 06:41:46.175044','2026-08-05 06:41:47.303018'),(25,'cs_9520dba667d047bd918c472e95971216','COMPLETED','상담원은 상대방의 목소리가 들리지 않는 상황에서 통신 상태를 확인하고 안내를 완료했다.',NULL,NULL,NULL,NULL,'2026-08-05 07:21:12.246818','2026-08-05 07:21:13.441036'),(26,'cs_e2d16704d81e46aea6c04fa644ab1376','COMPLETED','상담원은 자막 오류 문제를 해결하기 위해 상담원의 마이크 위치와 이어폰 사용 여부를 확인하고 안내했다.',NULL,NULL,NULL,NULL,'2026-08-05 07:27:07.803281','2026-08-05 07:27:08.763485'),(27,'cs_12ac4dc5d7224da583dddd26afff7be9','COMPLETED','상담원은 현재 위치 확인 및 카메라 오류 문제에 대한 안내를 완료했습니다.',NULL,NULL,NULL,NULL,'2026-08-05 07:34:44.609541','2026-08-05 07:34:45.772898'),(28,'cs_6c3efb06f8b949eba402f3ab822842b9','COMPLETED','상담원: 네, 무엇을 도와드릴까요?',NULL,NULL,NULL,NULL,'2026-08-05 07:37:55.067526','2026-08-05 07:37:56.079637'),(29,'cs_debb89101435404ca9c101fd385bae66','COMPLETED','상담원은 카메라 작동 여부와 관련된 문의에 대해 1시간 전쯤 마지막으로 확인했음을 안내했다.',NULL,NULL,NULL,NULL,'2026-08-05 07:42:25.921032','2026-08-05 07:42:26.935949'),(30,'cs_db82968a22934c6483088cc181d82e02','COMPLETED','상담원은 형훈의 휴대폰 카메라 작동 오류에 대해 안내했다.',NULL,NULL,NULL,NULL,'2026-08-05 08:27:53.594199','2026-08-05 08:27:54.656275'),(31,'cs_bfecca3c131c4c8baec498f01ed0b5db','COMPLETED','상담원이 역내 안내를 시작함.',NULL,NULL,NULL,NULL,'2026-08-05 08:33:16.041463','2026-08-05 08:33:16.901700'),(32,'cs_0e07ab770f5f4dbdaf7149a9f7fd1fea','COMPLETED','상담원이 카메라가 보이지 않는다고 안내 완료.',NULL,NULL,NULL,NULL,'2026-08-05 08:34:37.346623','2026-08-05 08:34:38.433203'),(33,'cs_9a4eb3e49ac74ea6ab983cbc51ebdb6e','COMPLETED','상담원은 승객의 문의에 대한 답변을 준비하기 위해 잠시 대기했다.',NULL,NULL,NULL,NULL,'2026-08-06 01:17:01.124707','2026-08-06 01:17:02.055628'),(34,'cs_8d4ab91311704621a497aa6b1a385c62','COMPLETED','상담원은 상대방의 목소리가 들리지 않는 상황에 대해 안내했다.',NULL,NULL,NULL,NULL,'2026-08-06 03:06:24.029498','2026-08-06 03:06:25.004909'),(35,'cs_8fb07a95dcb74f14b2391a7bdb1f94b1','COMPLETED','상담원은 지하철역 실내 안내를 시작하며 상대방에게 잘 들리는지 확인했다.',NULL,NULL,NULL,NULL,'2026-08-06 03:24:16.573616','2026-08-06 03:24:17.565201'),(36,'cs_5784b51b96a64a899c9d620fff4b1d08','COMPLETED','상담원이 승객에게 지하철역 내부로 들어오라고 안내 완료.',NULL,NULL,NULL,NULL,'2026-08-06 03:25:59.621970','2026-08-06 03:26:00.753082'),(37,'cs_e2fc5f15cfaa4d59822b29bda3601db8','COMPLETED','상담원은 상대방의 목소리가 들리지만, 시스템상으로 수신되지 않는 상황에 대한 안내를 완료했다.',NULL,NULL,NULL,NULL,'2026-08-06 03:27:20.397211','2026-08-06 03:27:21.369996'),(38,'cs_fee48bd43c084ad7b594a991e3d6de44','COMPLETED','상담원은 영어 번역 기능은 있으나 자막 기능이 작동하지 않는 문제에 대한 안내를 완료했다.',NULL,NULL,NULL,NULL,'2026-08-06 03:29:59.778113','2026-08-06 03:30:00.940331'),(39,'cs_112d75d6dac74b318ad4a90242fbb6af','COMPLETED','상담원은 사용자에게 더 길게 말하도록 안내했다.',NULL,NULL,NULL,NULL,'2026-08-06 05:10:49.708097','2026-08-06 05:10:50.671082'),(40,'cs_c7598d46ea8242c19fa06acce13581bf','COMPLETED','상담원은 상대방의 목소리가 들리지 않아 안내를 진행하지 못함.',NULL,NULL,NULL,NULL,'2026-08-06 05:50:19.670690','2026-08-06 05:50:20.684628'),(41,'cs_bc7a096e945045ec8fcbc617c6f471fe','COMPLETED','상담원이 안내를 시작했으나 구체적인 내용은 파악되지 않음.',NULL,NULL,NULL,NULL,'2026-08-06 05:51:17.934395','2026-08-06 05:51:19.023782'),(42,'cs_0060478f376a4715b295841709efac2f','COMPLETED','상담원은 구글 슬라이드 또는 현재 상태에서 발표 흐름과 키워드를 정하는 것을 안내했다.',NULL,NULL,NULL,NULL,'2026-08-06 06:37:28.434561','2026-08-06 06:37:29.501496'),(43,'cs_cd50eacc70354dfdb265b5c95475e9a2','COMPLETED','상담원은 사용자의 현재 위치와 목적지를 파악하여 길 찾기를 돕는 방법을 안내했다.',NULL,NULL,NULL,NULL,'2026-08-06 06:45:37.513241','2026-08-06 06:45:38.762687'),(44,'cs_911d8f4fc53c4d6f968632c36e6c4d0c','COMPLETED','상담자는 지하철역 내부 안내를 진행했습니다.',NULL,NULL,NULL,NULL,'2026-08-06 07:29:18.466048','2026-08-06 07:29:19.529927'),(45,'cs_5e0b06b88c8342f4805efe7d2314daef','COMPLETED','상담원은 사용자의 음성 인식 및 자막 번역 기능 작동 여부를 확인하고 안내했다.',NULL,NULL,NULL,NULL,'2026-08-06 07:33:02.370955','2026-08-06 07:33:03.505564'),(46,'cs_44e4e0fb767b4a90a020ba2b22cfc18d','COMPLETED','상담자는 승객의 감사 인사에 대해 \"천만에요\"라고 응대 완료.',NULL,NULL,NULL,NULL,'2026-08-06 08:41:05.204067','2026-08-06 08:41:06.230607');
