DROP TABLE IF EXISTS `consultation_transcript`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `consultation_transcript` (
  `transcript_id` bigint NOT NULL AUTO_INCREMENT,
  `consultation_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `seq` int NOT NULL,
  `speaker` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `translated_content` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`transcript_id`),
  UNIQUE KEY `uk_consultation_transcript_seq` (`consultation_id`,`seq`),
  KEY `idx_consultation_transcript_consultation` (`consultation_id`,`seq`),
  CONSTRAINT `fk_consultation_transcript_session` FOREIGN KEY (`consultation_id`) REFERENCES `consultation_session` (`consultation_id`)
) ENGINE=InnoDB AUTO_INCREMENT=399 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

