  CONSTRAINT `fk_facility_floor` FOREIGN KEY (`floor_id`) REFERENCES `station_floor` (`floor_id`),
  CONSTRAINT `fk_facility_linked_node` FOREIGN KEY (`linked_node_id`) REFERENCES `route_node` (`node_id`),
  CONSTRAINT `fk_facility_station` FOREIGN KEY (`station_id`) REFERENCES `station` (`station_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1073 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
