DROP TABLE IF EXISTS `floor_map`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `floor_map` (
  `map_id` bigint NOT NULL AUTO_INCREMENT,
  `floor_id` bigint NOT NULL,
  `map_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `map_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '지도 파일 URL. NULL 이면 클라이언트가 자체 이미지를 사용한다',
  `width` int DEFAULT NULL,
  `height` int DEFAULT NULL,
  `scale_m_per_px` decimal(10,6) DEFAULT NULL,
  `origin_px_x` decimal(10,3) DEFAULT NULL COMMENT '캐노니컬 원점(0,0)에 대응하는 이미지 픽셀 x',
  `origin_px_y` decimal(10,3) DEFAULT NULL COMMENT '캐노니컬 원점(0,0)에 대응하는 이미지 픽셀 y',
  `frame_angle_deg` decimal(10,4) DEFAULT NULL COMMENT '캐노니컬 +X축과 이미지 x축의 각도(도)',
  `version` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  PRIMARY KEY (`map_id`),
  KEY `fk_floor_map_floor` (`floor_id`),
  CONSTRAINT `fk_floor_map_floor` FOREIGN KEY (`floor_id`) REFERENCES `station_floor` (`floor_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
