DROP TABLE IF EXISTS `route_node`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `route_node` (
  `node_id` bigint NOT NULL AUTO_INCREMENT,
  `station_id` bigint NOT NULL,
  `floor_id` bigint NOT NULL,
  `node_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `map_x` decimal(10,3) NOT NULL,
  `map_y` decimal(10,3) NOT NULL,
  `map_z` decimal(10,3) DEFAULT NULL,
  `is_landmark` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  PRIMARY KEY (`node_id`),
  KEY `fk_route_node_floor` (`floor_id`),
  KEY `idx_route_node_station_floor` (`station_id`,`floor_id`),
  CONSTRAINT `fk_route_node_floor` FOREIGN KEY (`floor_id`) REFERENCES `station_floor` (`floor_id`),
  CONSTRAINT `fk_route_node_station` FOREIGN KEY (`station_id`) REFERENCES `station` (`station_id`)
) ENGINE=InnoDB AUTO_INCREMENT=359 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
